; modes.asm -- chapter 8: one load of each addressing mode
; generated by gen08.py
        INCLUDE "msx.inc"
        OUTPUT "modes.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
var     EQU RAM_START + $40     ; the RAM copy of value
; HL, BC and IX point at var; nothing uses the stack after the copy.
init:   di
        ld sp, SYS_AREA
        ld hl, (value)          ; value, from the cartridge ...
        ld (var), hl
        ld hl, (value + 2)
        ld (var + 2), hl        ; ... to var, in the RAM, which keeps a store
        ld hl, var
        ld bc, var
        ld ix, var
t0:     ld a,b                  ; register
t1:     ld a,$12                ; immediate
t2:     ld a,(hl)               ; register indirect
t3:     ld a,(bc)               ; register indirect
t4:     ld a,(var)              ; direct
t5:     ld a,(ix+2)             ; indexed
t6:     ld (hl),$12             ; immediate to register indirect
t7:     ld (ix+2),$12           ; immediate to indexed
t8:     ld hl,$1234             ; immediate, 16 bits
t9:     ld hl,(var)             ; direct, 16 bits
t10:    ld bc,(var)             ; direct, 16 bits
t11:    ld ix,(var)             ; direct, 16 bits
t12:    ld (var),hl             ; direct, 16 bits
t13:    ld sp,hl                ; register, 16 bits
t14:    ex de,hl                ; exchange
t15:    ld a,i                  ; register
t16:
stop:   jr stop

value:  dw $1234
        dw $5678
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
